<script setup>
import {computed} from 'vue';
import {documentRecognition as text} from '../locales/document-recognition.js';
import {reportMoney,reportDate} from '../services/report-format.js';
const props=defineProps({recognition:Object,extraction:Object});
const visible=computed(()=>props.recognition&&props.recognition.status!=='not_analyzed');
const values=computed(()=>{const data=props.extraction||{};return [[text.fields.name,data.supplier?.name||data.customer?.name||text.pending],[text.fields.reference,data.reference||text.pending],[text.fields.date,data.invoice_date?reportDate(data.invoice_date):text.pending],[text.fields.base,data.base_total==null?text.pending:reportMoney(data.base_total)+' €'],[text.fields.tax,data.tax_total==null?text.pending:reportMoney(data.tax_total)+' €'],[text.fields.total,data.total_amount==null?text.pending:reportMoney(data.total_amount)+' €']];});
</script>
<template><section v-if="visible" class="document-recognition" :aria-label="text.detectedData"><p><strong>{{ text.kinds[recognition.kind] }}</strong> · <span class="badge">{{ text.statuses[recognition.status] }}</span></p><p v-if="recognition.kind==='unreadable'" class="muted">{{ text.manual }}</p><template v-else-if="recognition.kind!=='document'"><dl><div v-for="[label,value] in values" :key="label"><dt>{{ label }}</dt><dd>{{ value }}</dd></div></dl><p v-if="recognition.missing?.length" class="muted">{{ text.missing }}: {{ recognition.missing.join(', ') }}.</p><p v-if="recognition.multiple_invoices" class="notice">{{ text.multiple }}</p><p v-if="recognition.remembered_format" class="muted">{{ text.remembered }}: {{ recognition.remembered_format }}.</p></template></section></template>
<style scoped>.document-recognition{margin:10px 0;padding:12px;border:1px solid var(--border,#dce3e7);border-radius:8px;font-size:13px;white-space:normal}.document-recognition p{margin:0 0 8px}.document-recognition p:last-child{margin-bottom:0}.document-recognition dl{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:8px 16px;margin:8px 0}.document-recognition dt{font-size:12px;color:var(--muted,#596675)}.document-recognition dd{margin:2px 0;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}</style>
